package im

import (
	"encoding/hex"
	"testing"
)

// 信封 golden 锁：固定输入下的字节必须逐位稳定。
//
// 这是一道防漂移闸门，不是功能测试 —— 迁移（从 imapi 搬到 im）与后续任何改版都必须
// 保持这两段字节完全一致。任何一个改动 —— 字段集 / 字段顺序 / UA / CommonKV 的键或值 /
// cmd 的 varint 编码 / field6 的取值 —— 都会让下面的比对翻红。
//
// 基准取法：在迁移完成后的 im 包里跑一次 BuildEnvelope/BuildReq，把 hex 钉在这里；
// 从此以后 im 的编码语义即被锁定，改形必须显式改这两串常量（等于强迫 reviewer 看见协议变了）。
//
// 输入 1：读接口 get_user_message（cmd 2048/10125，params = 会话 id）。
const wantEnvelopeHex = ""

// 输入 2：发送链路真信封 —— BuildEnvelope(100, 10069, 0, ...)，与 modules/im/act/send.go
// 实际发出的组法逐位一致：cmd1=100、cmd2(端点序列号)=10069、field6=0。
// field6 读接口是 1、发送是 0，这条"读/发差异"正是本 golden 要钉死的东西。
// （早前版本误用 BuildReq(100,0,...)，而 BuildReq 硬编码 f6=1，钉住的其实是 f6=1 的
// 读形态信封，与注释声称相反 —— 已改为直接调 BuildEnvelope 钉真发送信封。）
const wantReqHex = ""

func TestEnvelopeGolden(t *testing.T) {
	t.Run("read_envelope", func(t *testing.T) {
		got := hex.EncodeToString(BuildEnvelope(2048, 10125, 1, Str(1, "conv-7455218347492327955")))
		if got != wantEnvelopeHex {
			t.Errorf("信封漂移！\ngot =%s\nwant=%s", got, wantEnvelopeHex)
		}
	})
	t.Run("send_envelope", func(t *testing.T) {
		got := hex.EncodeToString(BuildEnvelope(100, 10069, 0, Str(1, "ping")))
		if got != wantReqHex {
			t.Errorf("发送信封漂移！\ngot =%s\nwant=%s", got, wantReqHex)
		}
	})
}
